import { isUnaffordable as hoursUnaffordable, debitHours } from "./modules/time-service.js";
import { applyTravel } from "./modules/travel-service.js";
import { catalogEvidence } from "./modules/evidence-service.js";
import { filterSuspects, issueWarrant } from "./modules/dossier-service.js";
import { validateArrest } from "./modules/arrest-validator.js";
import { getCurrentState, transition, canArrest } from "./modules/state-machine.js";
const $=s=>document.querySelector(s),STORE="arquivo-zero-pursuit-v2",CAREER="arquivo-zero-career-v1",CAMPAIGN="arquivo-zero-campaign-v1",CITY_ART={sao_paulo:"sao-paulo",recife:"recife",brasilia:"brasilia",manaus:"manaus",porto_alegre:"porto-alegre"};let game,state,pendingDestination,campaign;
document.documentElement.classList.add("retro-ui");
document.querySelector(".top-actions").insertAdjacentHTML("afterbegin",'<span id="career-stars" class="career-stars" title="Estrelas acumuladas"><span class="material-symbols-outlined">star</span><strong>0</strong></span>');
const el={title:$("#game-title"),briefing:$("#briefing"),code:$("#case-code"),time:$("#time-left"),timeBar:$("#time-bar"),cityImage:$("#city-image"),cities:$("#city-layer"),lines:$("#route-lines"),locTitle:$("#location-title"),locName:$("#location-name"),locType:$("#location-type"),locDesc:$("#location-description"),citySummary:$("#city-summary"),cityFacts:$("#city-facts"),actions:$("#location-actions"),coords:$("#coords"),evidence:$("#evidence-list"),evidenceCount:$("#evidence-count"),route:$("#route-log"),visited:$("#visited-count"),travel:$("#travel-dialog"),dossier:$("#dossier-dialog"),notes:$("#notes-dialog"),message:$("#message-dialog"),notebook:$("#notebook"),chars:$("#char-count")};
function campaignOn(){return !!(game&&game.campaign&&game.campaign.chapters)}function saveKey(){return campaignOn()&&campaign?`${STORE}-${game.metadata.id}-${campaign.run[campaign.index]}`:`${STORE}-${game.metadata.id}`}function writeCampaign(){if(campaignOn()&&campaign)localStorage.setItem(`${CAMPAIGN}-${game.campaign.id}`,JSON.stringify(campaign))}function startCampaign(){const pool=[...game.campaign.lieutenant_pool],run=[],n=game.campaign.lieutenant_chapters||2;while(run.length<n&&pool.length){const i=Math.floor(Math.random()*pool.length);run.push(pool.splice(i,1)[0])}run.push(game.campaign.boss);campaign={run,index:0};writeCampaign();return campaign}function readCampaign(){try{const raw=JSON.parse(localStorage.getItem(`${CAMPAIGN}-${game.campaign.id}`)||"null");if(Array.isArray(raw?.run)&&raw.run.length){campaign=raw;return campaign}}catch{}return startCampaign()}function applyChapter(){if(!campaignOn()||!campaign)return;const ch=game.campaign.chapters[campaign.run[campaign.index]];if(!ch)return;game.culprit=ch.culprit;if(ch.start)game.metadata.start=ch.start;if(ch.briefing)game.metadata.briefing=ch.briefing;if(ch.total_hours)game.metadata.total_hours=ch.total_hours;if(ch.arrest_requirements)game.arrest_requirements=ch.arrest_requirements;if(ch.scenarios)game.scenarios=ch.scenarios}
function isolateSave(reason){try{const key=saveKey(),raw=localStorage.getItem(key);if(raw!=null)localStorage.setItem(`${key}.invalid`,raw);localStorage.removeItem(key)}catch{}console.info("AZ: save isolado",String(reason||"desconhecido"))}
function restoreState(){let parsed;try{parsed=JSON.parse(localStorage.getItem(saveKey())||"null")}catch{isolateSave("json-invalido");return fresh()}if(!parsed||typeof parsed!=="object")return fresh();if(!game.locations.some(x=>x.id===parsed.location)){isolateSave("localizacao");return fresh()}if((game.scenarios||[]).length&&parsed.scenario&&!game.scenarios.some(s=>s.id===parsed.scenario)){isolateSave("cenario");return fresh()}if(campaignOn()&&campaign&&!game.campaign.chapters[campaign.run?.[campaign.index]]){isolateSave("capitulo");startCampaign();applyChapter();return fresh()}return parsed}
function adaptCase(raw){const warnings=[];if(!raw||typeof raw!=="object"||Array.isArray(raw))return{normalized:raw,warnings,version:null};const declared=raw.schemaVersion,version=typeof declared==="string"?declared.startsWith("3")?"3.x":declared.startsWith("2")?"2.x":declared.startsWith("1")?"1.x":raw.campaign?"2.x":"1.x":raw.campaign?"2.x":"1.x",normalized=Object.assign({},raw);if(version==="3.x")return{normalized,warnings,version};if(!raw.schemaVersion)warnings.push({path:"schemaVersion",message:`Ausente; tratado como ${version}`});normalized.schemaVersion=version==="1.x"?"1.x":"2.x";normalized.evidence=(raw.evidence||[]).map((item,index)=>{if(!item||typeof item!=="object")return item;if(item.admissibility!=null&&item.integrity!=null&&item.quality!==undefined)return item;const id=item.id||String(index);if(item.admissibility==null)warnings.push({path:`evidence.${id}.admissibility`,message:"Ausente; preenchido com unknown"});return Object.assign({admissibility:"unknown",quality:null,integrity:"unverified"},item)});return{normalized,warnings,version}}
async function loadGame(src="game.json?v=campaign-001"){try{const rawCase=typeof src==="string"?await fetch(src).then(r=>r.json()):src;const adapted=adaptCase(rawCase);game=adapted.normalized;for(const warning of adapted.warnings)console.warn("[AZ-ADAPT]",warning.path,warning.message);if(!game?.metadata?.id||!game.locations?.length||!game.travel||!game.dossier)throw Error("Estrutura mínima ausente.");if(campaignOn()){readCampaign();applyChapter()}else campaign=null;state=restoreState();if(game.scenarios?.length&&!state.scenario){state.scenario=pickScenario();save()}render()}catch(e){show("CASO INVÁLIDO","Falha ao abrir",e.message)}}
function pickScenario(exclude=null){const candidates=[];for(const item of game.scenarios||[])if(item.id!==exclude)candidates.push(item);const pool=candidates.length?candidates:game.scenarios||[];return pool.length?pool[Math.floor(Math.random()*pool.length)].id:null}function scenario(){for(const item of game.scenarios||[])if(item.id===state.scenario)return item;return null}function actionData(action){return Object.assign({},action,scenario()?.action_overrides?.[action.id]||{})}function fresh(previousScenario=null){return{location:game.metadata.start,hours:game.metadata.total_hours,visited:[game.metadata.start],route:[game.metadata.start],evidence:[],actions:[],notes:"",warrant:false,warrantSuspect:null,finished:false,rewarded:false,scenario:pickScenario(previousScenario)}}
function save(){localStorage.setItem(saveKey(),JSON.stringify(state))}function loc(id=state.location){return game.locations.find(x=>x.id===id)}function ev(id){const base=game.evidence.find(x=>x.id===id);return base?Object.assign({},base,scenario()?.evidence_overrides?.[id]||{}):base}
function render(){const current=loc();if(!current){isolateSave("render");state=fresh();save();if(!loc()){show("CASO INVÁLIDO","Localização ausente","O caso não declara a cidade inicial.");return}return render()}const active=scenario();el.title.textContent=game.metadata.title;el.briefing.textContent=game.metadata.briefing;el.code.textContent=active?.code?(campaignOn()&&campaign?`${game.metadata.code} · ${campaign.run[campaign.index]} · ${active.code}`:`${game.metadata.code} · ${active.code}`):game.metadata.code;el.cityImage.src=`assets/cities/${CITY_ART[state.location]||"sao-paulo"}.webp`;el.cityImage.alt=`Vista em pixel art de ${current.name}`;el.notebook.value=state.notes||"";chars();career();clock();map();place();evidence();route();dossier()}
function clock(){el.time.textContent=`${Math.max(0,state.hours)}h`;el.timeBar.style.width=`${Math.max(0,state.hours)/game.metadata.total_hours*100}%`;el.time.closest(".location-header").classList.toggle("danger",state.hours<=16)}
function isUnaffordable(cost,allowZero=false){return hoursUnaffordable(state.hours,cost,allowZero)}
function map(){const active=scenario(),navigation=active?.navigation||game.navigation,allowed=new Set(navigation[state.location]||[]),visible=[];for(const city of game.locations)if(city.id===state.location||state.visited.includes(city.id)||allowed.has(city.id))visible.push(city);el.cities.innerHTML=visible.map(c=>{const current=c.id===state.location,visited=state.visited.includes(c.id),canGo=allowed.has(c.id),cost=canGo?game.travel[state.location][c.id]:0;return`<button class="city ${current?"current":visited?"visited":""}" style="left:${c.x}%;top:${c.y}%" data-city="${c.id}" ${current||!canGo||state.finished||canGo&&isUnaffordable(cost)?"disabled":""} aria-label="${current?c.name+", posição atual":"Viajar para "+c.name+", "+cost+" horas"}"><span class="city-pulse"></span><span class="city-name">${escape(c.name)}</span><small>${current?"POSIÇÃO ATUAL":visited&&!canGo?"VISITADA":cost+"h"}</small></button>`}).join("");el.cities.querySelectorAll(".city:not(:disabled)").forEach(b=>b.onclick=()=>openTravel(b.dataset.city));const pts=state.route.map(id=>loc(id)).map(c=>`${c.x*10},${c.y*6.2}`).join(" ");el.lines.innerHTML=`<polyline points="${pts}" fill="none" stroke="#d6ff54" stroke-width="2" stroke-dasharray="7 8" vector-effect="non-scaling-stroke"/>`}
function place(){const l=loc(),info=l.city_info||{},facts=Array.isArray(info.facts)?info.facts:[];el.locTitle.textContent=l.name;el.locName.textContent=l.name;el.locType.textContent=l.type;el.locDesc.textContent=l.description;el.citySummary.textContent=info.summary||"Contexto local ainda não disponível para este caso.";let factHtml="";for(const fact of facts)factHtml+=`<li>${escape(fact)}</li>`;el.cityFacts.innerHTML=factHtml;el.coords.textContent=l.coords;el.actions.innerHTML=l.actions.map(base=>{const a=actionData(base),done=state.actions.includes(a.id),locked=a.requires_warrant&&!state.warrant,icon=done?"check":locked?"lock":"search";return`<button class="investigate ${done?"done":""}" data-action="${a.id}" ${done||locked||state.finished||isUnaffordable(a.cost,!!a.arrest)?"disabled":""}><span class="material-symbols-outlined">${icon}</span><strong>${escape(a.label)}</strong><small>${done?"CONCLUÍDO":locked?"EXIGE MANDADO":a.arrest?"VERIFICAR IDENTIDADE · "+a.cost+"h":a.cost+"h"}</small></button>`}).join("");el.actions.querySelectorAll(".investigate:not(:disabled)").forEach(b=>b.onclick=()=>act(b.dataset.action))}
function evidence(){const found=[];for(const item of game.evidence)if(state.evidence.includes(item.id))found.push(ev(item.id));el.evidenceCount.textContent=`${found.length} ${found.length===1?"catalogada":"catalogadas"}`;el.evidence.innerHTML=found.length?found.map(e=>`<article class="evidence found"><div><span>${e.id}</span><em>${e.tag}</em></div><h3>${escape(e.title)}</h3><p>${escape(e.text)}</p></article>`).join(""):'<div class="empty-state"><span>ARQUIVO LACRADO</span><strong>Nenhuma prova catalogada</strong><p>Investigue a cidade atual para revelar evidências admissíveis.</p></div>'}
function route(){const count=new Set(state.visited).size;el.visited.textContent=`${count} ${count===1?"cidade":"cidades"}`;el.route.innerHTML=state.route.map((id,i)=>`<div class="route-item"><span>${String(i+1).padStart(2,"0")}</span><i></i><strong>${loc(id).name}</strong></div>`).join("")}
function openTravel(id){pendingDestination=id;const d=loc(id),cost=game.travel[state.location][id];$("#travel-title").textContent=`Rota para ${d.name}`;$("#travel-copy").innerHTML=`O deslocamento consumirá <strong>${cost} horas</strong>. Restarão <strong>${Math.max(0,state.hours-cost)} horas</strong>.`;el.travel.showModal()}
$("#confirm-travel").onclick=()=>{const nav=scenario()?.navigation||game.navigation,moved=applyTravel(state,game,pendingDestination,nav);if(!moved.ok){el.travel.close();show("SALDO INSUFICIENTE","Deslocamento recusado","O custo excede as horas restantes. Nenhum tempo foi consumido.");return}Object.assign(state,moved.newState);transition(state,"TRAVEL");save();el.travel.close();$("#map-dialog").close();render()};
function act(id){const a=actionData(loc().actions.find(x=>x.id===id));if(a.arrest&&!canArrest(getCurrentState(state))){show("PROCEDIMENTO INVÁLIDO","Abordagem recusada","É necessário um mandado válido antes da abordagem.");return}if(isUnaffordable(a.cost,!!a.arrest)){show("SALDO INSUFICIENTE","Ação recusada","O custo excede as horas restantes. Nenhum tempo foi consumido.");return}if(!spend(a.cost,a.arrest))return;transition(state,"ACTION");state.actions.push(id);if(a.evidence)state.evidence=catalogEvidence(state,a.evidence).evidence;save();render();if(a.arrest&&state.warrant){state.finished=true;const decision=validateArrest(state,game);if(decision.reasons.includes("wrong_warrant")){transition(state,"ARREST_INVALID");save();render();show("MANDADO NÃO CORRESPONDENTE",game.ending.wrong_warrant_title,game.ending.wrong_warrant_text,false,true)}else if(decision.decision!=="APPROVED"){transition(state,"ARREST_INVALID");save();render();show("CONJUNTO PROBATÓRIO INSUFICIENTE",game.ending.insufficient_evidence_title,game.ending.insufficient_evidence_text,false,true)}else{transition(state,"ARREST_VALID");awardStar();save();render();show("PRISÃO LEGALMENTE VALIDADA",game.ending.win_title,`${a.result}\n\n${game.ending.win_text}\n\n★ Uma estrela foi adicionada à sua carreira.`,false,true)}}else show(a.evidence?`EVIDÊNCIA ${a.evidence}`:"PISTA INCONCLUSIVA",a.evidence?ev(a.evidence).title:"Tempo consumido",a.result)}
function spend(h,allowZero=false){const result=debitHours(state,h,allowZero);if(!result.ok){transition(state,"TIMEOUT");state.hours=0;state.finished=true;save();render();closeAll();show("PRAZO ENCERRADO",game.ending.lose_title,game.ending.lose_text,false,true);return false}state.hours=result.hours;return true}
function dossier(){const f=$("#dossier-form"),evidenceLabel=state.evidence.length===1?"catalogada":"catalogadas";f.innerHTML=game.dossier.fields.map(x=>`<label><span>${x.label}</span><select name="${x.id}"><option value="">DESCONHECIDO</option>${x.options.map(o=>`<option>${o}</option>`).join("")}</select></label>`).join("")+`<div class="dossier-status"><span>BASE DE SUSPEITOS</span><strong>consulta por atributos</strong></div><div class="dossier-status"><span>PROVAS REUNIDAS</span><strong>${state.evidence.length} ${evidenceLabel}</strong></div><button class="primary wide" ${state.warrant||state.finished?"disabled":""}>${state.warrant?"MANDADO EMITIDO":"CRUZAR ATRIBUTOS"}</button>`;f.onsubmit=submitDossier;const command=$("#dossier-button"),label=command.querySelector("strong");label.textContent=state.warrant?"MANDADO ✓":"DOSSIÊ";command.classList.toggle("issued",state.warrant)}
function submitDossier(e){e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget)),chosen=Object.entries(data).filter(([,v])=>v);if(!chosen.length){el.dossier.close();show("DOSSIÊ VAZIO","Nenhum atributo informado","Investigue testemunhas e informe ao menos uma característica.");return}const matches=filterSuspects(game,chosen);el.dossier.close();if(matches.length!==1){show("CRUZAMENTO INCONCLUSIVO",matches.length?`${matches.length} suspeitos possíveis`:"Nenhum suspeito encontrado",matches.length?matches.map(s=>s.name).join(" · "):"Revise os atributos: a combinação não existe na base.");return}Object.assign(state,issueWarrant(state,matches[0].id));transition(state,"WARRANT");save();render();show("MANDADO APROVADO",`Mandado contra ${matches[0].name}`,"O perfil produziu uma única correspondência. Agora localize e capture o suspeito antes do prazo.")}
function career(){const stars=Number(localStorage.getItem(CAREER)||0);$("#career-stars strong").textContent=stars}function awardStar(){if(state.rewarded)return;localStorage.setItem(CAREER,String(Number(localStorage.getItem(CAREER)||0)+1));state.rewarded=true}function newCase(){closeAll();if(campaignOn()&&state.rewarded&&campaign){if(campaign.index<campaign.run.length-1){campaign.index++;writeCampaign();applyChapter();state=fresh()}else{startCampaign();applyChapter();state=fresh()}}else{const previous=state.scenario;state=fresh(previous)}save();render();scrollTo({top:0,behavior:"smooth"})}
function show(k,t,c,html=false,final=false){$("#message-kicker").textContent=k;$("#message-title").textContent=t;$("#message-copy").innerHTML=escape(c).replace(/\n/g,"<br>");const button=el.message.querySelector(".primary.wide");button.textContent=final?campaignOn()&&state.rewarded&&campaign&&campaign.index<campaign.run.length-1?"PRÓXIMO CAPÍTULO":campaignOn()&&state.rewarded?"NOVA CAMPANHA":"INICIAR NOVO CASO":"CONTINUAR";button.onclick=final?newCase:()=>el.message.close();el.message.showModal()}function escape(v){const d=document.createElement("div");d.textContent=String(v);return d.innerHTML}function closeAll(){document.querySelectorAll("dialog[open]").forEach(d=>d.close())}
$("#dossier-button").onclick=()=>el.dossier.showModal();$("#notes-button").onclick=()=>el.notes.showModal();$("#map-button").onclick=()=>$("#map-dialog").showModal();$("#evidence-button").onclick=()=>$("#evidence-dialog").showModal();document.querySelectorAll("[data-close]").forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());el.notebook.oninput=()=>{state.notes=el.notebook.value;chars();save()};function chars(){el.chars.textContent=`${el.notebook.value.length} caracteres`}$("#reset-button").onclick=()=>resetChapter();$("#reset-campaign-button").onclick=()=>resetCampaign();$("#reset-career-button").onclick=()=>resetCareer();$("#json-input").onchange=e=>{importCase(e.target.files[0]);e.target.value=""};
function resetChapter(){if(!confirm("Reiniciar este capítulo? O progresso do capítulo será apagado. A campanha e as estrelas são preservadas."))return;const previous=state.scenario;localStorage.removeItem(saveKey());state=fresh(previous);save();render()}
function resetCampaign(){if(!confirm("Reiniciar a campanha? Um novo conjunto de capítulos será sorteado e o capítulo atual será apagado. As estrelas são preservadas."))return;localStorage.removeItem(saveKey());if(campaignOn()){startCampaign();applyChapter()}state=fresh();save();render()}
function resetCareer(){if(!confirm("Zerar a carreira? Todas as estrelas serão apagadas. O capítulo e a campanha atuais permanecem."))return;localStorage.removeItem(CAREER);career()}
async function importCase(file){const max=524288;if(!file)return;if(file.size>max){show("CASO INVÁLIDO","Arquivo grande demais","O limite de importação é 512 KiB.");return}try{const raw=await file.text();let data;try{data=JSON.parse(raw)}catch(err){show("CASO INVÁLIDO","JSON inválido",err.message);return}await loadGame(data)}catch(err){show("CASO INVÁLIDO","Falha ao ler arquivo",err.message)}}
async function scene(){try{const THREE=await import("https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js"),canvas=$("#scene"),s=new THREE.Scene(),c=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,.1,100);c.position.z=6;const r=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true});r.setPixelRatio(Math.min(devicePixelRatio,1.5));r.setSize(innerWidth,innerHeight);const g=new THREE.Mesh(new THREE.IcosahedronGeometry(2.8,3),new THREE.MeshBasicMaterial({color:0x4bd6c8,wireframe:true,transparent:true,opacity:.06}));g.position.x=.8;s.add(g);for(let i=0;i<80;i++){const d=new THREE.Mesh(new THREE.SphereGeometry(.008,5,5),new THREE.MeshBasicMaterial({color:0xd6ff54,transparent:true,opacity:.5}));d.position.set((Math.random()-.5)*10,(Math.random()-.5)*7,(Math.random()-.5)*3);s.add(d)}(function a(){g.rotation.y+=.0007;r.render(s,c);requestAnimationFrame(a)})();addEventListener("resize",()=>{c.aspect=innerWidth/innerHeight;c.updateProjectionMatrix();r.setSize(innerWidth,innerHeight)})}catch{}}scene();loadGame();
